14: export class CargarArchivoComponent {
15:   archivo: File | null = null; // Único archivo seleccionado
16:   @ViewChild("fileInput", { static: false }) fileInput!: ElementRef;
17: 
18:   constructor(
19:     public dialogRef: MatDialogRef<CargarArchivoComponent>,
20:     private PlanAnualAuditoriaMid: PlanAnualAuditoriaMid,
21:     private nuxeoService: NuxeoService,
22:     private alertService: AlertService,
23:     private modalService: ModalService,
24:     private referenciaPdfService: ReferenciaPdfService,
25: 
26:     @Inject(MAT_DIALOG_DATA) public data: {
27:       tipoArchivo: string;
28:       idTipoDocumento: number;
29:       descripcion: string;
30:       id: string;
31:       vigenciaId: number;
32:       cargaLambda: boolean;
33:       tipo: string;
34:       tipoIdReferencia: number;
35:     }
36:   ) { }
37: 
38:   onArchivoSelecionado(event: any): void {
39:     const input = event.target as HTMLInputElement;
40:     const file = input.files ? input.files[0] : null;
41: 
42:     if (file) {
43:       if (
44:         (this.data.tipoArchivo === "pdf" && file.type !== "application/pdf") ||
45:         (this.data.tipoArchivo === "xlsx" &&
46:           file.type !== "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
47: 
48:       ) {
49:         alert("Por favor seleccione un archivo válido según el tipo especificado.");
50:         this.removerArchivo();
51:         return;
52:       }
53: 
54:       this.archivo = file;
55:     }
56:   }
57: 
58:   onArchivoInputClick(): void {
59:     this.fileInput.nativeElement.click();
60:   }
61: 
62:   removerArchivo(): void {
63:     this.archivo = null;
64:     this.fileInput.nativeElement.value = "";
65:   }
66: 
67:   cargarArchivo(): void {
68:     if (!this.archivo) {
69:       this.alertService.showErrorAlert("No se ha seleccionado ningún archivo.");
70:       return;
71:     }
72: 
73: 
74:     if (this.data.cargaLambda) {
75:       this.cargarConLambda().then(success => {
76:         if (success) {
77:           this.cargarConNuxeo().then(nuxeoResponse => {
78:             this.guardarReferencia(nuxeoResponse, "Plan Auditoria",this.data.id, 0, false);
79: 
80:           });
81:         }
82:       });
83:     } else {
84:       this.cargarConNuxeo().then(nuxeoResponse => {
85:         this.guardarReferencia(nuxeoResponse, "Plan Auditoria", this.data.id, this.data.tipoIdReferencia, true);
86:       });
87:     }
88:   }
89: 
90:   private async cargarConLambda(): Promise<boolean> {
91:     try {
92:       const base64 = await this.nuxeoService.fileABase64(this.archivo!);
93:       console.log("vigencia Masivo",  this.data.vigenciaId);
94: 
95:       let payload: any = {};
96:       switch (this.data.tipo) {
97:         case "auditorias":
98:           payload = {
99:             base64data: base64,
100:             complement: { plan_auditoria_id: this.data.id, vigencia_id: this.data.vigenciaId },
101:             type_upload: "auditorias",
102:           };
103:           break;
104:         case "actividades":
105:           payload = {
106:             base64data: base64,
107:             complement: { auditoria_id: this.data.id },
108:             type_upload: "actividades",
109:           };
110:           break;
111:       }
112: 
113:       const response: any = await this.PlanAnualAuditoriaMid
114:         .post(`cargue-masivo/${this.data.tipo}`, payload)
115:         .toPromise();
116: 
117:       if (response && response.Data) {
118:         console.log("Archivo enviado exitosamente al MID", response);
119:         this.resultados(response.Data);
120:         return true;
121:       } else {
122:         this.alertService.showErrorAlert(
123:           "La respuesta de Lambda no contiene datos válidos."
124:         );
125:         return false;
126:       }
127:     } catch (error) {
128:       this.alertService.showErrorAlert(
129:         "Error al enviar el archivo a Lambda. Por favor, revise el log."
130:       );
131:       console.error("Error al enviar el archivo al MID", error);
132:       return false;
133:     }
134:   }
135: 
136:   private async cargarConNuxeo(): Promise<any> {
137:     const archivoConDatos = {
138:       IdTipoDocumento: this.data.idTipoDocumento,
139:       nombre: this.archivo!.name,
140:       descripcion: this.data.descripcion,
141:       file: this.archivo!,
142:     };
143: 
144:     return new Promise((resolve, reject) => {
145:       this.nuxeoService.guardarArchivos([archivoConDatos]).subscribe({
146:         next: (response) => {
147:           console.log("Archivo subido a Nuxeo", response);
148:           this.dialogRef.close();
149:           resolve(response[0]);
150:         },
151:         error: (error) => {
152:           this.alertService.showErrorAlert("Error al subir el archivo.");
153:           console.error("Error al subir el archivo", error);
154:           reject(error);
155:         },
156:       });
157:     });
158:   }
159: 
160:   guardarReferencia(nuxeoResponse: any, referencia_tipo: string, referencia_id: string, tipo_id: number, mostrarMensaje: boolean): void {
161:     if (nuxeoResponse.res.Enlace) {
162:       this.referenciaPdfService
163:         .guardarReferencia(nuxeoResponse.res, referencia_tipo, referencia_id, tipo_id)
164:         .subscribe({
165:           next: (response) => {
166:             console.log("Referencia guardada exitosamente", response);
167:             if (mostrarMensaje) {
168:               this.alertService.showSuccessAlert("Archivo subido exitosamente.");
169:             }
170:           },
171:           error: (error) => {
172:             console.error("Error al guardar la referencia", error);
173:           },
174:         });
175:     }
176:   }
177: 
178:   resultados(data: any): void {
179:     let mensaje = "";
180: 
181:     if (data.Erróneos?.length > 0) {
182:       mensaje += `<strong>Se encontraron los siguientes errores en algunos registros:</strong><ul><br>`;
183:       data.Erróneos.forEach((error: any) => {
184:         mensaje += `<li><strong>Fila ${error.Idx}:</strong> ${error.Error}</li>`;
185:       });
186:       mensaje += `</ul>`;
187:     }
188: 
189:     if (data.Correctos?.length > 0) {
190:       mensaje += `<br><strong>Registros correctos:</strong><ul>`;
191:       mensaje += data.Correctos.join(", ") + '<br><br>';
192:     }
193: 
194:     this.modalService.mostrarModal(mensaje, 'warning', '');
195:   }
196: 
197: }

